"""Generates migration 026 from skills_vocabulary.json, so the SQL and the
vocabulary cannot disagree."""
import json, pathlib

voc = json.load(open('apps/ai-engine/eval/corpus_sources/skills_vocabulary.json', encoding='utf-8'))
skills, aliases = voc['skills'], voc['aliases']

def lit(s): return "'" + s.replace("'", "''") + "'"

lines = []
lines.append("""-- Expands the skills vocabulary from 27 terms to the full set, and adds the
-- alias table the CV parser needs.
--
-- GENERATED by scripts/generate_skill_vocabulary_migration.py from
-- apps/ai-engine/eval/corpus_sources/skills_vocabulary.json. Do not hand-edit:
-- change the builder and regenerate, or the vocabulary the parser matches
-- against and the vocabulary the database serves will drift apart.
--
-- Why this had to grow. skill_categories held 5 categories and 27 skills --
-- Python, JavaScript, React, Content Writing, Graphic Design and so on. A CV
-- parser matching against 27 terms would read almost nothing from a real
-- Kenyan CV, which is as likely to say welding, tailoring, boda boda or
-- M-Pesa agency work as it is to say React. Three sources, recorded in the
-- builder's docstring: KeSCO-2022 occupational titles (de-inverted from the
-- national standard's index form), terms observed on robots.txt-permitted
-- Kenyan job-listing pages, and curated informal-sector additions.
--
-- The existing 27 are preserved: every one is in the curated list, and the
-- insert below is additive per category rather than a replacement, so no gig
-- already tagged with one of them is orphaned.
""")

lines.append("-- ---------------------------------------------------------------------------")
lines.append("-- 1. The vocabulary")
lines.append("-- ---------------------------------------------------------------------------\n")

for cat in sorted(skills):
    arr = ", ".join(lit(s) for s in skills[cat])
    lines.append(f"-- {cat}: {len(skills[cat])} skills")
    lines.append("INSERT INTO public.skill_categories (name, skills)")
    lines.append(f"VALUES ({lit(cat)}, ARRAY[{arr}]::TEXT[])")
    lines.append("ON CONFLICT (name) DO UPDATE SET skills = EXCLUDED.skills;\n")

lines.append("""-- ---------------------------------------------------------------------------
-- 2. Aliases
-- ---------------------------------------------------------------------------
--
-- CVs abbreviate. A parser that only matched the canonical form would miss
-- most real mentions: "JS", "MS Excel", "book keeping", "fundi", "boda".
-- Lower-cased on the way in, so lookup is a plain equality test.

CREATE TABLE IF NOT EXISTS public.skill_aliases (
  alias     TEXT PRIMARY KEY,
  canonical TEXT NOT NULL
);

ALTER TABLE public.skill_aliases ENABLE ROW LEVEL SECURITY;

-- Reference data, readable by anyone signed in. There is no write policy:
-- the vocabulary is generated, not user-editable.
DROP POLICY IF EXISTS "Anyone may read skill aliases" ON public.skill_aliases;
CREATE POLICY "Anyone may read skill aliases"
  ON public.skill_aliases FOR SELECT
  USING (true);
""")

pairs = ",\n  ".join(f"({lit(a.lower())}, {lit(c)})" for a, c in sorted(aliases.items()))
lines.append("INSERT INTO public.skill_aliases (alias, canonical) VALUES")
lines.append(f"  {pairs}")
lines.append("ON CONFLICT (alias) DO UPDATE SET canonical = EXCLUDED.canonical;\n")

out = pathlib.Path('supabase/migrations/026_skill_vocabulary.sql')
out.write_text("\n".join(lines), encoding='utf-8')
total = sum(len(v) for v in skills.values())
print(f"wrote {out} — {total} skills, {len(aliases)} aliases")
